int _checkedWireInt(BigInt value) {
  final signed = value.toSigned(64);
  if (signed.abs() > BigInt.from(9007199254740991)) {
    throw RangeError('Use the BigInt field for an exact 64-bit value');
  }
  return signed.toInt();
}

